mapper.select:
SELECT osm_type || '/' || osm_id AS "buildingId", NULLIF(BTRIM(name), '') AS "name", NULLIF(BTRIM(tags ->> 'building'), '') AS "buildingType",
AS "heightMeters",
AS "heightSource", NULLIF(min_height_m, 0) AS "minHeightMeters", NULLIF(levels, 0) AS "levels", NULLIF(BTRIM(CONCAT_WS(' ', NULLIF(tags ->> 'addr:postcode', ''), NULLIF(tags ->> 'addr:city', ''), NULLIF(tags ->> 'addr:district', ''), NULLIF(tags ->> 'addr:street', ''), NULLIF(tags ->> 'addr:housenumber', '') )), '') AS "address", to_char(source_updated_at AT TIME ZONE 'Asia/Seoul', 'YYYY-MM-DD HH24:MI:SS') AS "sourceUpdatedAt", to_char(imported_at AT TIME ZONE 'Asia/Seoul', 'YYYY-MM-DD HH24:MI:SS') AS "importedAt", tags::text AS "tagsJson" FROM gis.building WHERE osm_type = #{osmType} AND osm_id = #{osmId}
